// Subscribe once, for example in the form constructor:
menuMain.ItemClicked += menuMain_ItemClicked;

private void menuMain_ItemClicked(object sender, ToolStripItemClickedEventArgs e)
{
    tslStatus.Text = "Clicked " + e.ClickedItem.Text;
}

// Subscribe once, for example in the form constructor:
menuMain.MenuActivate += menuMain_MenuActivate;

private void menuMain_MenuActivate(object sender, EventArgs e)
{
    tslStatus.Text = "Menu active";
}

// Subscribe once, for example in the form constructor:
menuMain.MenuDeactivate += menuMain_MenuDeactivate;

private void menuMain_MenuDeactivate(object sender, EventArgs e)
{
    tslStatus.Text = "Ready";
}

// Subscribe once, for example in the form constructor:
ctxMenu.Opening += ctxMenu_Opening;

private void ctxMenu_Opening(object sender, CancelEventArgs e)
{
    bool hasSelection = txtEditor.SelectionLength > 0;
    mnuCopy.Enabled = hasSelection;
    mnuCut.Enabled = hasSelection;
}

// Subscribe once, for example in the form constructor:
ctxMenu.Opened += ctxMenu_Opened;

private void ctxMenu_Opened(object sender, EventArgs e)
{
    tslStatus.Text = "Context menu opened";
}

// Subscribe once, for example in the form constructor:
ctxMenu.Closing += ctxMenu_Closing;

private void ctxMenu_Closing(object sender, ToolStripDropDownClosingEventArgs e)
{
    tslStatus.Text = "Menu closed because: " + e.CloseReason;
}

// Subscribe once, for example in the form constructor:
ctxMenu.ItemClicked += ctxMenu_ItemClicked;

private void ctxMenu_ItemClicked(object sender, ToolStripItemClickedEventArgs e)
{
    tslStatus.Text = "You chose " + e.ClickedItem.Text;
}

// Subscribe once, for example in the form constructor:
toolMain.ItemClicked += toolMain_ItemClicked;

private void toolMain_ItemClicked(object sender, ToolStripItemClickedEventArgs e)
{
    tslStatus.Text = e.ClickedItem.Text + " clicked";
}

// Subscribe once, for example in the form constructor:
toolMain.ItemAdded += toolMain_ItemAdded;

private void toolMain_ItemAdded(object sender, ToolStripItemEventArgs e)
{
    e.Item.ToolTipText = e.Item.Text;
}

// Subscribe once, for example in the form constructor:
toolMain.ItemRemoved += toolMain_ItemRemoved;

private void toolMain_ItemRemoved(object sender, ToolStripItemEventArgs e)
{
    lblCount.Text = toolMain.Items.Count + " items";
}

// Subscribe once, for example in the form constructor:
statusMain.ItemClicked += statusMain_ItemClicked;

private void statusMain_ItemClicked(object sender, ToolStripItemClickedEventArgs e)
{
    MessageBox.Show("You clicked " + e.ClickedItem.Text);
}

// Subscribe once, for example in the form constructor:
tsbBold.Click += tsbBold_Click;

private void tsbBold_Click(object sender, EventArgs e)
{
    rtbEditor.SelectionFont = new Font(rtbEditor.Font, FontStyle.Bold);
}

// Subscribe once, for example in the form constructor:
tsbBold.CheckedChanged += tsbBold_CheckedChanged;

private void tsbBold_CheckedChanged(object sender, EventArgs e)
{
    rtbEditor.SelectionFont = new Font(rtbEditor.Font, tsbBold.Checked ? FontStyle.Bold : FontStyle.Regular);
}

// Subscribe once, for example in the form constructor:
tslLink.Click += tslLink_Click;

private void tslLink_Click(object sender, EventArgs e)
{
    // requires: using System.Diagnostics;
    tslLink.LinkVisited = true;
    Process.Start(new ProcessStartInfo("https://dotnet.microsoft.com") { UseShellExecute = true });
}

// Subscribe once, for example in the form constructor:
tslLink.TextChanged += tslLink_TextChanged;

private void tslLink_TextChanged(object sender, EventArgs e)
{
    Text = "Status: " + tslLink.Text; // here Text is the form's title
}

// Subscribe once, for example in the form constructor:
tscZoom.SelectedIndexChanged += tscZoom_SelectedIndexChanged;

private void tscZoom_SelectedIndexChanged(object sender, EventArgs e)
{
    rtbEditor.ZoomFactor = float.Parse(tscZoom.SelectedItem.ToString().TrimEnd('%')) / 100f;
}

// Subscribe once, for example in the form constructor:
tscZoom.TextChanged += tscZoom_TextChanged;

private void tscZoom_TextChanged(object sender, EventArgs e)
{
    tslStatus.Text = "Typed: " + tscZoom.Text;
}

// Subscribe once, for example in the form constructor:
tscZoom.DropDown += tscZoom_DropDown;

private void tscZoom_DropDown(object sender, EventArgs e)
{
    if (tscZoom.Items.Count == 0)
    {
        tscZoom.Items.AddRange(new object[] { "50%", "100%", "200%" });
    }
}
